-- TES: pre-migration conflict inspection for migration 0037 (driver identity integrity and exclusive assignment).
-- READ ONLY: SELECT statements only. Nothing is merged, ended, corrected or deleted. Run it with a read-only role BEFORE 0037 is applied:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f scripts/database/preflight-0037-driver-identity.sql
-- Every query returns zero rows when the migration can be applied. Any row returned is a pre-existing conflict that must be resolved by an
-- authorized review first (migration 0037 refuses to apply while one exists). The output contains internal record ids, so keep it inside TES.
-- The canonical expressions below are generated from the same mapping as tes_security.canonical_* in migration 0037.
SET default_transaction_read_only = on;

\echo '1. Current licences held under equivalent jurisdiction/number spellings (same canonical licence, more than one active current row)'
WITH k AS (SELECT l.id, l.person_id, l.jurisdiction_country, l.jurisdiction_region, l.licence_number_display, l.effective_from,
