      ELSE replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_region, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') END) AS region, upper(regexp_replace(l.licence_number_display, '[^A-Za-z0-9]', '', 'g')) AS number FROM public.driver_licences l WHERE l.record_status = 'active')
SELECT a.id AS licence_a, b.id AS licence_b, a.country, a.region, a.number
  FROM k a JOIN k b ON a.id < b.id AND a.country = b.country AND a.region = b.region AND a.number = b.number
   AND daterange(a.effective_from, a.effective_to, '[)') && daterange(b.effective_from, b.effective_to, '[)');

\echo '3. Driver identities holding more than one open company assignment'
SELECT person_id, count(*) AS open_assignments, array_agg(organization_id ORDER BY organization_id) AS organization_ids, array_agg(id ORDER BY id) AS relationship_ids
  FROM public.organization_driver_relationships WHERE record_status = 'active' AND effective_to IS NULL
 GROUP BY person_id HAVING count(*) > 1;

\echo '4. Overlapping assignment periods for one driver identity'
SELECT a.person_id, a.id AS relationship_a, b.id AS relationship_b
  FROM public.organization_driver_relationships a JOIN public.organization_driver_relationships b
    ON a.id < b.id AND a.person_id = b.person_id AND a.record_status = 'active' AND b.record_status = 'active'
   AND daterange(a.effective_from, a.effective_to, '[)') && daterange(b.effective_from, b.effective_to, '[)');

\echo '5. Informational: current licences whose country or region will not canonicalize to a code (they stay readable; new writes of that spelling are refused)'
WITH k AS (SELECT l.id, l.person_id, l.jurisdiction_country, l.jurisdiction_region, (CASE
      WHEN replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_country, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') IN ('CA', 'CAN', 'CANADA') THEN 'CA'
      WHEN replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_country, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') IN ('US', 'USA', 'UNITED STATES', 'UNITED STATES OF AMERICA') THEN 'US'
      WHEN replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_country, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') IN ('MX', 'MEX', 'MEXICO') THEN 'MX'
      ELSE replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_country, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') END) AS country, (CASE
      WHEN replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_region, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') IN ('ALBERTA') THEN 'AB'
