      WHEN replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_region, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') IN ('VERACRUZ') THEN 'VER'
      WHEN replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_region, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') IN ('YUCATAN') THEN 'YUC'
      WHEN replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_region, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') IN ('ZACATECAS') THEN 'ZAC'
      ELSE replace(replace(upper(btrim(regexp_replace(translate(normalize(coalesce(l.jurisdiction_region, ''), NFC), 'ÁÀÂÄÉÈÊËÍÌÎÏÓÒÔÖÚÙÛÜÑÇáàâäéèêëíìîïóòôöúùûüñç', 'AAAAEEEEIIIIOOOOUUUUNCaaaaeeeeiiiioooouuuunc'), '[\s_-]+', ' ', 'g'))), '.', ''), ',', '') END) AS region, upper(regexp_replace(l.licence_number_display, '[^A-Za-z0-9]', '', 'g')) AS number FROM public.driver_licences l WHERE l.record_status = 'active')
SELECT id, person_id, jurisdiction_country, jurisdiction_region FROM k WHERE number = '' OR (CASE
      WHEN region IN ('AB', 'BC', 'MB', 'NB', 'NL', 'NS', 'NT', 'NU', 'ON', 'PE', 'QC', 'SK', 'YT') THEN 'CA'
      WHEN region IN ('AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'DC', 'FL', 'GA', 'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD', 'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ', 'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC', 'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY', 'PR', 'GU', 'VI', 'AS', 'MP') THEN 'US'
      WHEN region IN ('AGU', 'BCN', 'BCS', 'CAM', 'CHP', 'CHH', 'CMX', 'COA', 'COL', 'DUR', 'GUA', 'GRO', 'HID', 'JAL', 'MEX', 'MIC', 'MOR', 'NAY', 'NLE', 'OAX', 'PUE', 'QUE', 'ROO', 'SLP', 'SIN', 'SON', 'TAB', 'TAM', 'TLA', 'VER', 'YUC', 'ZAC') THEN 'MX'
 ELSE NULL END) IS DISTINCT FROM country;
